import argparse
import json
from pathlib import Path
from typing import Any, List, Optional, Sequence, Tuple

import numpy as np

import duckdb

DIM = 768  # CodeBERT


def load_vector(vec_source: str) -> np.ndarray:
    """
    Load a 768-d float vector from:
      - .npy:      numpy array (shape [768] or [1,768])
      - .json:     list of 768 floats
      - .txt:      768 floats separated by spaces or commas
      - JSON string literal like: "[0.1, 0.2, ...]"
    """
    p = Path(vec_source)
    if p.suffix.lower() == ".npy" and p.exists():
        arr = np.load(p)
    elif p.suffix.lower() == ".json" and p.exists():
        arr = np.asarray(json.loads(p.read_text()), dtype=np.float32)
    elif p.suffix.lower() == ".txt" and p.exists():
        txt = p.read_text().strip()
        parts = [t for t in txt.replace(",", " ").split() if t]
        arr = np.asarray([float(x) for x in parts], dtype=np.float32)
    else:
        # Try to parse as JSON literal directly (handy for quick tests)
        try:
            arr = np.asarray(json.loads(vec_source), dtype=np.float32)
        except Exception as _:
            raise ValueError(
                f"Cannot load vector from '{vec_source}'. "
                "Use a .npy/.json/.txt file or a JSON list literal."
            )

    arr = np.asarray(arr, dtype=np.float32).reshape(-1)
    if arr.shape[0] != DIM:
        raise ValueError(f"Vector must be length {DIM}, got shape {arr.shape}.")
    return arr


def maybe_normalize(v: np.ndarray) -> np.ndarray:
    n = np.linalg.norm(v)
    return (v / n) if n > 0 else v


def build_where(filters: dict, params: List[Any]) -> str:
    """
    Build WHERE clause for optional filters.
    Supported keys: lang, split, include_langs (list), include_splits (list),
                    exclude_uid, uid_prefix
    """
    clauses = []

    if filters.get("lang"):
        clauses.append("lang = ?")
        params.append(filters["lang"])

    if filters.get("split"):
        clauses.append('"split" = ?')  # split is a keyword in some engines; quote it
        params.append(filters["split"])

    if filters.get("include_langs"):
        incl = filters["include_langs"]
        placeholders = ",".join("?" for _ in incl)
        clauses.append(f"lang IN ({placeholders})")
        params.extend(incl)

    if filters.get("include_splits"):
        incl = filters["include_splits"]
        placeholders = ",".join("?" for _ in incl)
        clauses.append(f'"split" IN ({placeholders})')
        params.extend(incl)

    if filters.get("exclude_uid"):
        clauses.append("uid <> ?")
        params.append(filters["exclude_uid"])

    if filters.get("uid_prefix"):
        clauses.append("uid LIKE ?")
        params.append(filters["uid_prefix"] + "%")

    return ("WHERE " + " AND ".join(clauses)) if clauses else ""


def search(
    db_path: str,
    table: str,
    qvec: np.ndarray,
    k: int,
    ef_search: Optional[int],
    filters: dict,
    show_columns: Sequence[str],
) -> List[Tuple]:
    con = duckdb.connect(db_path, read_only=True)
    try:
        con.execute("LOAD vss;")
        if ef_search is not None:
            con.execute("SET hnsw_ef_search = ?;", [int(ef_search)])

        params: List[Any] = []
        where_sql = build_where(filters, params)

        # Build SELECT list
        base_cols = ", ".join(show_columns)
        sql = f"""
            SELECT {base_cols},
                   array_cosine_distance(embedding, ?::FLOAT[{DIM}]) AS dist
            FROM {table}
            {where_sql}
            ORDER BY dist
            LIMIT {k};
        """

        # parameters: filters first, then vector at the end
        params_with_vec = params + [qvec.tolist()]
        return con.execute(sql, params_with_vec).fetchall()
    finally:
        con.close()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--db", default="duckdb/plag.db", help="DuckDB database file")
    ap.add_argument(
        "--table", default="plag.main.embeddings", help="Table with vectors"
    )
    ap.add_argument(
        "--vec", required=True, help="Vector source (.npy/.json/.txt or JSON list)"
    )
    ap.add_argument(
        "--normalize", action="store_true", help="L2-normalize the query vector"
    )
    ap.add_argument("--k", type=int, default=20, help="Top-k results")
    ap.add_argument(
        "--ef-search", type=int, default=None, help="Override HNSW ef_search"
    )
    ap.add_argument("--lang", help="Filter: exact lang")
    ap.add_argument("--split", help="Filter: exact split")
    ap.add_argument("--include-langs", nargs="*", help="Filter: lang IN (...)")
    ap.add_argument("--include-splits", nargs="*", help="Filter: split IN (...)")
    ap.add_argument("--exclude-uid", help="Filter: exclude this uid")
    ap.add_argument("--uid-prefix", help="Filter: uid LIKE '<prefix>%%'")
    ap.add_argument(
        "--columns",
        nargs="*",
        default=["uid", "lang", "split"],
        help="Columns to return",
    )
    args = ap.parse_args()

    q = load_vector(args.vec)
    if args.normalize:
        q = maybe_normalize(q)

    filters = {
        "lang": args.lang,
        "split": args.split,
        "include_langs": args.include_langs,
        "include_splits": args.include_splits,
        "exclude_uid": args.exclude_uid,
        "uid_prefix": args.uid_prefix,
    }

    rows = search(
        db_path=args.db,
        table=args.table,
        qvec=q,
        k=args.k,
        ef_search=args.ef_search,
        filters=filters,
        show_columns=args.columns,
    )

    # Pretty print
    if not rows:
        print("No results.")
        return

    # Header
    header = args.columns + ["dist"]
    widths = [max(len(h), 10) for h in header]
    print(" | ".join(h.ljust(w) for h, w in zip(header, widths)))
    print("-+-".join("-" * w for w in widths))
    for r in rows:
        line = []
        for i, val in enumerate(r):
            s = (
                f"{val:.6f}"
                if (i == len(r) - 1 and isinstance(val, float))
                else str(val)
            )
            line.append(s.ljust(widths[i]))
        print(" | ".join(line))


if __name__ == "__main__":
    main()
